#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <linux/kvm.h>
#include <pthread.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <time.h>

static int (*real_ioctl)(int, unsigned long, ...);
static void *(*real_mmap)(void *, size_t, int, int, int, off_t);
static struct kvm_run *runs[65536];
static int vcpus[65536];
static double last[65536];
static int port[65536];
static uint64_t counts[65536];
static double service[65536];
static uint64_t pages[256], page_counts[256];
static double page_service[256], page_first[256], page_last[256];
static int nr_pages, previous_page[65536];
static uint64_t irq_calls;
static FILE *out;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static char debug[4096];
static size_t debug_len;
static int first_serial, summaries, lcr;
static double start;

static double now(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec / 1e9;
}

static void summary(double t) {
    fprintf(out, "{\"kind\":\"ports\",\"t\":%.9f,\"irq_line_calls\":%lu,\"ports\":{", t, irq_calls);
    int comma = 0;
    for (int p = 0; p < 65536; p++) if (counts[p])
        fprintf(out, "%s\"%x\":[%lu,%.9f]", comma++ ? "," : "", p, counts[p], service[p]);
    fprintf(out, "},\"mmio\":{");
    for (int i = 0; i < nr_pages; i++)
        fprintf(out, "%s\"%lx\":[%lu,%.9f,%.9f,%.9f]", i ? "," : "", pages[i], page_counts[i], page_service[i], page_first[i], page_last[i]);
    fprintf(out, "}}\n");
    fflush(out);
}

__attribute__((constructor)) static void init(void) {
    real_ioctl = dlsym(RTLD_NEXT, "ioctl");
    real_mmap = dlsym(RTLD_NEXT, "mmap");
    const char *path = getenv("PERF5_EARLY");
    start = now();
    if (path) out = fopen(path, "w");
    if (out) { fprintf(out, "{\"kind\":\"exec\",\"t\":%.9f}\n", start); fflush(out); }
}

int ioctl(int fd, unsigned long request, ...) {
    va_list args;
    va_start(args, request);
    unsigned long arg = va_arg(args, unsigned long);
    va_end(args);
    if (out && request == KVM_RUN && fd >= 0 && fd < 65536 && last[fd] && !first_serial) {
        pthread_mutex_lock(&lock);
        double elapsed = now() - last[fd];
        if (previous_page[fd]) page_service[previous_page[fd]-1] += elapsed;
        else service[port[fd]] += elapsed;
        pthread_mutex_unlock(&lock);
    }
    int result = real_ioctl(fd, request, arg);
    int saved_errno = errno;
    if (!out) return result;
    double t = now();
    pthread_mutex_lock(&lock);
    if (request == KVM_IRQ_LINE && !first_serial) irq_calls++;
    if (request == KVM_CREATE_VCPU && result >= 0 && result < 65536) vcpus[result] = 1;
    if (request == KVM_CREATE_VM || request == KVM_CREATE_VCPU || (request == KVM_IOEVENTFD && t-start<3)) {
        fprintf(out, "{\"kind\":\"kvm\",\"t\":%.9f,\"request\":%lu,\"arg\":%lu,\"result\":%d}\n", t, request, arg, result);
        if (request == KVM_IOEVENTFD) {
            struct kvm_ioeventfd *event = (void *)arg;
            fprintf(out, "{\"kind\":\"ioevent\",\"t\":%.9f,\"address\":%lu,\"length\":%u,\"match\":%lu,\"flags\":%u}\n",t,event->addr,event->len,event->datamatch,event->flags);
        }
        fflush(out);
    }
    if (request == KVM_RUN && result == 0 && fd >= 0 && fd < 65536 && runs[fd]) {
        struct kvm_run *run = runs[fd];
        if (!last[fd]) { fprintf(out, "{\"kind\":\"first_exit\",\"t\":%.9f,\"fd\":%d}\n", t, fd); fflush(out); }
        last[fd] = t;
        port[fd] = 0;
        previous_page[fd] = 0;
        if (run->exit_reason == KVM_EXIT_MMIO && !first_serial) {
            uint64_t page = run->mmio.phys_addr & ~4095ull;
            int i;
            for (i = 0; i < nr_pages && pages[i] != page; i++);
            if (i == nr_pages && nr_pages < 256) { pages[i] = page; page_first[i] = t; nr_pages++; }
            if (i < nr_pages) { previous_page[fd] = i+1; page_counts[i]++; page_last[i] = t; }
        }
        if (run->exit_reason == KVM_EXIT_IO) {
            int p = run->io.port;
            port[fd] = p;
            if (!first_serial) counts[p]++;
            if (run->io.direction == KVM_EXIT_IO_OUT) {
                char *bytes = (char *)run + run->io.data_offset;
                size_t len = run->io.size * run->io.count;
                if (p == 0x3fb) lcr = bytes[0];
                if (p == 0x402) for (size_t i = 0; i < len; i++) {
                    char c = bytes[i];
                    if (c == '\n' || debug_len == sizeof(debug)-1) {
                        debug[debug_len] = 0;
                        fprintf(out, "{\"kind\":\"bios\",\"t\":%.9f,\"text\":\"", t);
                        for (size_t j=0;j<debug_len;j++) {
                            if (debug[j] == '"' || debug[j] == '\\') fputc('\\', out);
                            if ((unsigned char)debug[j] >= 32) fputc(debug[j], out);
                        }
                        fprintf(out, "\"}\n"); fflush(out); debug_len=0;
                    } else debug[debug_len++]=c;
                }
                if (p == 0x3f8 && !(lcr & 128) && (unsigned char)bytes[0] >= 32 && (unsigned char)bytes[0] <= 126 && !first_serial) {
                    fprintf(out, "{\"kind\":\"first_uart_write\",\"t\":%.9f,\"byte\":%u}\n", t, (unsigned char)bytes[0]);
                    summary(t); first_serial=1;
                }
            }
        }
        if (!first_serial && t-start > summaries * .5 && summaries < 20) { summary(t); summaries++; }
    }
    pthread_mutex_unlock(&lock);
    errno = saved_errno;
    return result;
}

void *mmap64(void *address, size_t size, int prot, int flags, int fd, off64_t offset) {
    return mmap(address, size, prot, flags, fd, offset);
}

void *mmap(void *address, size_t size, int prot, int flags, int fd, off_t offset) {
    void *result = real_mmap(address,size,prot,flags,fd,offset);
    if (fd >= 0 && fd < 65536 && vcpus[fd] && !offset && result != MAP_FAILED) runs[fd] = result;
    return result;
}
